// Builds a Y4M file whose every frame is a printed EAN-13 barcode, for
// Chromium's --use-file-for-fake-video-capture. Without it a headless
// browser has no camera at all, and an unrendered scan path is not evidence.
//
// The barcode is drawn from the EAN-13 tables here rather than fetched or
// generated by a library: F58 needs a real symbol a real decoder reads, and
// the encoding is 40 lines. No dependency enters the project for a test
// fixture.
//
// Takes a 13-digit EAN-13 or a 12-digit UPC-A. A UPC-A symbol IS the EAN-13
// symbol for the same number with a leading zero: identical module pattern,
// identical guard bars, differing only in how the human-readable digits are
// printed beside the bars, which no decoder reads. So a 12-digit argument is
// drawn from its 0-prefixed EAN-13 form, and what the browser decodes is the
// same bar pattern a real pack carries.
//
// This matters because macOS Vision, which backs BarcodeDetector in Chromium
// here, reports that symbol as format "ean_13" with the leading zero
// restored. That is the read the catalogue's 30 barcode_upca rows have to
// survive, and F58's first pass never exercised it: its fixture was a
// genuine EAN-13 (5032921014762), so the format that works was tested and
// the format that breaks was not.
//
// Usage: node make-barcode-y4m.mjs <12-or-13-digit-code> <out.y4m>

import { writeFileSync } from "node:fs";

const L = ["0001101","0011001","0010011","0111101","0100011","0110001","0101111","0111011","0110111","0001011"];
const G = ["0100111","0110011","0011011","0100001","0011101","0111001","0000101","0010001","0001001","0010111"];
const R = L.map((s) => [...s].map((c) => (c === "0" ? "1" : "0")).join(""));
const PARITY = ["LLLLLL","LLGLGG","LLGGLG","LLGGGL","LGLLGG","LGGLLG","LGGGLL","LGLGLG","LGLGGL","LGGLGL"];

export function ean13Modules(code) {
  if (!/^\d{13}$/.test(code)) throw new Error(`not 13 digits: ${code}`);
  const d = [...code].map(Number);
  const sum = d.slice(0, 12).reduce((n, v, i) => n + v * (i % 2 === 0 ? 1 : 3), 0);
  const check = (10 - (sum % 10)) % 10;
  if (check !== d[12]) throw new Error(`check digit is ${check}, code says ${d[12]}`);
  const parity = PARITY[d[0]];
  let bits = "101";
  for (let i = 0; i < 6; i++) bits += (parity[i] === "L" ? L : G)[d[i + 1]];
  bits += "01010";
  for (let i = 0; i < 6; i++) bits += R[d[i + 7]];
  bits += "101";
  return bits;
}

const WIDTH = 640;
const HEIGHT = 480;
const MODULE = 5;
const QUIET = 12;
const BAR_H = 260;
const FRAMES = 8;

function lumaPlane(bits) {
  const y = Buffer.alloc(WIDTH * HEIGHT, 235); // paper white
  const barsWidth = (bits.length + QUIET * 2) * MODULE;
  const x0 = Math.round((WIDTH - barsWidth) / 2) + QUIET * MODULE;
  const y0 = Math.round((HEIGHT - BAR_H) / 2);
  for (let i = 0; i < bits.length; i++) {
    if (bits[i] !== "1") continue;
    for (let px = 0; px < MODULE; px++) {
      const x = x0 + i * MODULE + px;
      if (x < 0 || x >= WIDTH) continue;
      for (let row = y0; row < y0 + BAR_H; row++) y[row * WIDTH + x] = 16; // ink
    }
  }
  return y;
}

// A 12-digit UPC-A is widened to the EAN-13 form that draws the same bars.
export function toEan13(code) {
  const d = code.replace(/[^0-9]/g, "");
  if (d.length === 12) return `0${d}`;
  return d;
}

const [, , code = "5032921014762", out = "barcode.y4m"] = process.argv;
const symbol = toEan13(code);
const bits = ean13Modules(symbol);
const y = lumaPlane(bits);
const chroma = Buffer.alloc((WIDTH / 2) * (HEIGHT / 2), 128);
const parts = [Buffer.from(`YUV4MPEG2 W${WIDTH} H${HEIGHT} F30:1 Ip A1:1 C420mpeg2\n`)];
for (let f = 0; f < FRAMES; f++) parts.push(Buffer.from("FRAME\n"), y, chroma, chroma);
writeFileSync(out, Buffer.concat(parts));
const kind = code.replace(/[^0-9]/g, "").length === 12 ? "UPC-A" : "EAN-13";
console.log(
  `wrote ${out}: ${kind} ${code}` +
    (symbol === code ? "" : ` drawn as the EAN-13 symbol ${symbol}`) +
    `, ${bits.length} modules, ${FRAMES} frames, ${WIDTH}x${HEIGHT}`,
);
